const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const disruption_case_id = Number(input.disruption_case_id);
const mobile = text(input.mobile);
const decision = text(input.decision).toLowerCase();
const option_number = Number(input.option_number ?? 0);
const decision_note = text(input.decision_note);

const options_per_patient = Number(input.options_per_patient ?? 3);
const additional_search_days = Number(input.additional_search_days ?? 14);

const confirm_decision = toBoolean(input.confirm_decision);

const allowedDecisions = [
  'reschedule',
  'cancel',
  'waitlist',
  'more_options',
];

const errors = [];

if (
  !Number.isInteger(disruption_case_id) ||
  disruption_case_id < 1
) {
  errors.push({
    field: 'disruption_case_id',
    message: 'disruption_case_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل باید فقط شامل اعداد و در صورت نیاز علامت + باشد.',
  });
}

if (!allowedDecisions.includes(decision)) {
  errors.push({
    field: 'decision',
    message:
      'decision باید reschedule، cancel، waitlist یا more_options باشد.',
  });
}

if (
  decision === 'reschedule' &&
  (
    !Number.isInteger(option_number) ||
    option_number < 1
  )
) {
  errors.push({
    field: 'option_number',
    message: 'برای جابه‌جایی، شماره گزینه انتخاب‌شده الزامی است.',
  });
}

if (
  !Number.isInteger(options_per_patient) ||
  options_per_patient < 1 ||
  options_per_patient > 5
) {
  errors.push({
    field: 'options_per_patient',
    message: 'options_per_patient باید یک عدد صحیح بین 1 و 5 باشد.',
  });
}

if (
  !Number.isInteger(additional_search_days) ||
  additional_search_days < 1 ||
  additional_search_days > 60
) {
  errors.push({
    field: 'additional_search_days',
    message: 'additional_search_days باید یک عدد صحیح بین 1 و 60 باشد.',
  });
}

if (decision_note.length > 500) {
  errors.push({
    field: 'decision_note',
    message: 'یادداشت تصمیم نباید بیشتر از 500 کاراکتر باشد.',
  });
}

if (confirm_decision !== true) {
  errors.push({
    field: 'confirm_decision',
    message: 'تصمیم بیمار باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      disruption_case_id,
      mobile,
      decision,
      option_number,
      decision_note,
      options_per_patient,
      additional_search_days,
      confirm_decision,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

const db = $('Apply Patient Decision in Database').first().json;

const hasOldEvent = Boolean(db.old_calendar_event_id);

const hasDeleteError =
  Boolean($json.error) ||
  Boolean($json.errorMessage) ||
  $json.success === false;

let old_calendar_delete_status = 'not_required';

if (hasOldEvent) {
  old_calendar_delete_status = hasDeleteError
    ? 'delete_failed'
    : 'deleted';
}

return [
  {
    json: {
      ...db,
      old_calendar_delete_status,
    },
  },
];

