const db = $('Build Calendar Delete Context').first().json;
const saved = $json;

return [
  {
    json: {
      ...db,
      success: true,
      result: 'rescheduled',
      message: 'زمان جایگزین ثبت و Google Calendar به‌روزرسانی شد.',
      google_calendar_event_id:
        saved.google_calendar_event_id ?? null,
      calendar_sync_status:
        db.old_calendar_delete_status === 'delete_failed'
          ? 'recreated_old_delete_failed'
          : 'recreated',
    },
  },
];

const db = $('Build Calendar Delete Context').first().json;

return [
  {
    json: {
      ...db,
      success: true,
      result: 'rescheduled',
      message: 'زمان جایگزین در دیتابیس ثبت شد، اما ساخت رویداد جدید Google Calendar ناموفق بود.',
      google_calendar_event_id: null,
      calendar_sync_status: 'create_failed',
    },
  },
];

const data = $json;

return [
  {
    json: {
      ...data,
      calendar_sync_status:
        data.old_calendar_delete_status,
      calendar_sync_message:
        data.old_calendar_delete_status === 'delete_failed'
          ? 'تصمیم بیمار در دیتابیس ثبت شد، اما حذف رویداد قدیمی تقویم نیاز به بررسی دارد.'
          : data.old_calendar_delete_status === 'deleted'
            ? 'رویداد قدیمی Google Calendar حذف شد.'
            : 'برای این نوبت شناسه رویداد تقویم ثبت نشده بود.',
    },
  },
];

return [
  {
    json: {
      success: false,
      result: $json.result ?? 'decision_failed',
      message: $json.message ?? 'تصمیم بیمار اعمال نشد.',
      disruption_case_id: $json.disruption_case_id ?? null,
      appointment_id: $json.appointment_id ?? null,
      action: $json.action ?? null,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات تصمیم بیمار ناقص یا نامعتبر است.',
      errors: $json.errors ?? [],
    },
  },
];
